<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Librarian','Super Admin','College Admin');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){try{if($_POST['action']==='issue')db()->prepare("INSERT INTO library_transactions(copy_id,student_id,issued_at,return_due,status) VALUES(?,?,NOW(),DATE_ADD(CURDATE(),INTERVAL 14 DAY),'Issued')")->execute([(int)$_POST['copy_id'],(int)$_POST['student_id']]);elseif($_POST['action']==='return'){db()->prepare("UPDATE library_transactions SET returned_at=NOW(),status='Returned' WHERE id=?")->execute([(int)$_POST['id']]);}AuditService::log('LIBRARY','transactions',null,$_POST['action']);}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('transactions.php');}$active=db()->query("SELECT lt.*,u.name student, b.title,bc.accession_no FROM library_transactions lt JOIN students s ON s.id=lt.student_id JOIN users u ON u.id=s.user_id JOIN book_copies bc ON bc.id=lt.copy_id JOIN books b ON b.id=bc.book_id WHERE lt.status='Issued' ORDER BY lt.return_due")->fetchAll();$students=db()->query('SELECT s.id,u.name FROM students s JOIN users u ON u.id=s.user_id ORDER BY u.name')->fetchAll();$copies=db()->query("SELECT bc.id,bc.accession_no,b.title FROM book_copies bc JOIN books b ON b.id=bc.book_id WHERE bc.status='Available' ORDER BY b.title")->fetchAll();page_top('Library Circulation');flash();?><div class='card p-4 mb-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='action' value='issue'><div class='col-md-5'><select name='student_id' class='form-select' required><?php foreach($students as $x):?><option value='<?=e($x['id'])?>'><?=e($x['name'])?></option><?php endforeach;?></select></div><div class='col-md-5'><select name='copy_id' class='form-select' required><?php foreach($copies as $x):?><option value='<?=e($x['id'])?>'><?=e($x['title'].' · '.$x['accession_no'])?></option><?php endforeach;?></select></div><div class='col-md-2'><button class='btn btn-primary w-100'>Issue</button></div></form></div><div class='card p-3 table-responsive'><table class='table'><tr><th>Student</th><th>Book</th><th>Copy</th><th>Due</th><th>Action</th></tr><?php foreach($active as $r):?><tr><td><?=e($r['student'])?></td><td><?=e($r['title'])?></td><td><?=e($r['accession_no'])?></td><td><?=e($r['return_due'])?></td><td><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='action' value='return'><input type='hidden' name='id' value='<?=e($r['id'])?>'><button class='btn btn-sm btn-success'>Return</button></form></td></tr><?php endforeach;?></table></div><?php page_bottom();
